cpp_pointer_parameter.code:
#include <iostream>
#include <string>

void redirect(std::string* label, std::string* other) {
    label = other;
    *label = "changed";
}

int main() {
    std::string first = "draft";
    std::string second = "review";
    std::string* selected = &first;
    redirect(selected, &second);
    std::cout << first << '\n';
    std::cout << second << '\n';
    std::cout << *selected << '\n';
}

cpp_copy_in_out.code:
#include <iostream>

int adjust(int local) {
    local += 5;
    return local;
}

int main() {
    int quota = 10;
    int result = adjust(quota);
    std::cout << quota << '\n';
    quota = result;
    std::cout << quota << '\n';
}

cpp_macro_precedence.code:
#include <iostream>
#define SQUARE(x) x * x
#define GROUPED_SQUARE(x) ((x) * (x))

int main() {
    int first = SQUARE(2 + 3);
    int second = GROUPED_SQUARE(2 + 3);
    std::cout << first << '\n';
    std::cout << second << '\n';
}

cpp_macro_repeated_evaluation.code:
#include <iostream>
#define TWICE(action) do { action; action; } while (false)

void report_twice(int value) {
    std::cout << value << '\n';
    std::cout << value << '\n';
}

int main() {
    int count = 10;
    TWICE(++count);
    std::cout << count << '\n';
    report_twice(++count);
    std::cout << count << '\n';
}

cpp_macro_capture.code:
#include <iostream>
#define SWAP(X, Y) { int temp = X; X = Y; Y = temp; }

int main() {
    int a = 2;
    int temp = 17;
    SWAP(a, temp);
    std::cout << a << '\n';
    std::cout << temp << '\n';
}
